"""${{ values.name }} — generated by the rag-service blueprint (v7.2.0).

Business logic lives here; governed inference, tracing, retrieval scoping and metering
come from the platform SDK and library, so this file never names a model or a tenant
filter.
"""
import os
import pathlib

from platform_retrieval import Identity, InMemoryIndex, Retriever, TenantDirectory
from platform_sdk import Context, Gateway

HERE = pathlib.Path(__file__).resolve().parents[1]
PROMPT = (HERE / "prompts" / "answer.md").read_text()
TENANT = "${{ values.tenant }}"
gateway = Gateway(ctx=Context(tenant=TENANT, feature="answer"))


def answer(question: str, retriever, identity) -> tuple[str, list[str]]:
    hits = retriever.retrieve(question, identity=identity)
    passages = "\n".join(f"[{h.doc_id}] {h.text}" for h in hits)
    r = gateway.chat([{"role": "system", "content": PROMPT},
                      {"role": "user", "content": f"Question: {question}\n\nPassages:\n{passages}"}],
                     alias=os.environ.get("SERVICE_ALIAS", "${{ values.alias }}"))
    return r.text, [h.doc_id for h in hits[:2]]


def _eval_retriever():
    """The evaluation corpus (evals/warranty/corpus) in a local index: CI evaluates the
    prompts, alias and retrieval profile without production data."""
    ident = Identity("eval")
    idx = InMemoryIndex()
    for p in sorted((HERE / "evals" / "warranty" / "corpus").glob("*.md")):
        for section in p.read_text().split("\n## ")[1:]:
            title, _, body = section.partition("\n")
            idx.add("eval-tenant", f"policy/{p.name}#{title.strip().lower()}", body.strip())
    return Retriever(idx, TenantDirectory({"eval": "eval-tenant"}), k=4), ident


def eval_answer(question: str) -> tuple[str, list[str]]:
    retriever, ident = _eval_retriever()
    return answer(question, retriever, ident)
